'use strict';
const $=id=>document.getElementById(id);
const state={source:null,clean:null,region:null,mode:'ai',view:'compare',zoom:'fit',panX:0,panY:0,center:null,busy:false,worker:null,job:null,name:'image',generation:0};
let originalCanvas=document.createElement('canvas'),resultCanvas=document.createElement('canvas');
let drawBox=null,installPrompt=null,loadSerial=0;
function status(text,pct){$('statusText').textContent=text;$('progress').hidden=pct==null;if(pct!=null)$('progress').value=pct;}
function canWork(){const has=!!state.source;$('preview').disabled=!has||state.busy;$('run').disabled=!has||state.busy;$('save').disabled=!state.clean||!!state.region||state.busy;$('cancel').hidden=!state.busy;for(const el of document.querySelectorAll('.mode,#backend,#noise,#demo,#texture,#radius'))el.disabled=state.busy;}
function resetResult(){state.clean=null;state.region=null;$('cropBadge').hidden=true;$('engine').textContent='尚未處理';canWork();draw();}
function installImage(data,name){cancel(false);state.generation++;state.source=data;state.name=name||'image';state.center={x:Math.floor(data.width/2),y:Math.floor(data.height/2)};state.zoom='fit';state.panX=0;state.panY=0;originalCanvas.width=data.width;originalCanvas.height=data.height;originalCanvas.getContext('2d').putImageData(data,0,0);$('empty').hidden=true;$('display').hidden=false;$('dimensions').textContent=`${data.width.toLocaleString()} × ${data.height.toLocaleString()} px · 保留原尺寸`;$('fileInfo').textContent=state.name;$('exportHint').textContent='完成整張處理後即可匯出，不加浮水印。';resetResult();status('圖片就緒。可以先看局部，再清理整張。');}
async function loadFile(file){if(!file)return;const serial=++loadSerial;try{if(!/^image\/(png|jpeg|webp)$/.test(file.type)&&!(/\.(png|jpe?g|webp)$/i.test(file.name)))throw new Error('請使用 PNG、JPG 或 WebP。');const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});try{if(serial!==loadSerial)return;if(bitmap.width*bitmap.height>16000000)throw new Error('這張圖超過 1,600 萬像素，請先裁切或縮小後再試。');const c=document.createElement('canvas');c.width=bitmap.width;c.height=bitmap.height;c.getContext('2d').drawImage(bitmap,0,0);installImage(c.getContext('2d').getImageData(0,0,c.width,c.height),file.name);}finally{bitmap.close();}}catch(e){if(serial===loadSerial)status(e.message);}}
$('choose').onclick=()=>$('file').click();$('file').onchange=()=>{loadFile($('file').files[0]);$('file').value='';};
for(const event of ['dragenter','dragover'])document.addEventListener(event,e=>{e.preventDefault();$('choose').classList.add('drag');});
document.addEventListener('dragleave',e=>{if(!e.relatedTarget)$('choose').classList.remove('drag');});document.addEventListener('drop',e=>{e.preventDefault();$('choose').classList.remove('drag');loadFile(e.dataTransfer.files[0]);});
document.addEventListener('paste',e=>{const file=Array.from(e.clipboardData?.items||[]).find(x=>x.type.startsWith('image/'))?.getAsFile();if(file){e.preventDefault();loadFile(file);}});
for(const btn of document.querySelectorAll('.mode'))btn.onclick=()=>{if(state.busy)return;state.mode=btn.dataset.mode;for(const b of document.querySelectorAll('.mode')){b.classList.toggle('selected',b===btn);b.setAttribute('aria-pressed',b===btn?'true':'false');}$('aiSettings').hidden=state.mode!=='ai';$('fastSettings').hidden=state.mode!=='fast';resetResult();status('方式已切換，可以開始處理。');};
for(const id of ['texture','radius'])$(id).oninput=()=>{$('textureValue').value=$('texture').value;$('radiusValue').value=$('radius').value+' px';resetResult();status('清理設定已變更，請重新試看局部或清理整張。');};
$('noise').oninput=()=>{$('noiseValue').value=$('noise').value;resetResult();};$('backend').onchange=()=>{resetResult();if(state.worker){state.worker.terminate();state.worker=null;}};
$('mix').oninput=()=>{$('mixValue').value=$('mix').value+'%';renderResult();draw();};
function renderResult(){if(!state.source)return;const {width:w,height:h}=state.source;if(!state.clean)return;resultCanvas.width=w;resultCanvas.height=h;const ctx=resultCanvas.getContext('2d'),base=new Uint8ClampedArray(state.source.data),m=Number($('mix').value)/100;const rect=state.region||{x:0,y:0,width:w,height:h},clean=state.clean;for(let y=0;y<rect.height;y++)for(let x=0;x<rect.width;x++){const p=((rect.y+y)*w+rect.x+x)*4,q=(y*rect.width+x)*4;for(let c=0;c<3;c++)base[p+c]=base[p+c]*(1-m)+clean[q+c]*m;}ctx.putImageData(new ImageData(base,w,h),0,0);}
function draw(){if(!state.source)return;const c=$('display'),r=$('viewer').getBoundingClientRect(),dpr=window.devicePixelRatio||1;c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);const ctx=c.getContext('2d');ctx.scale(dpr,dpr);const w=state.source.width,h=state.source.height,scale=state.zoom==='fit'?Math.min(r.width/w,r.height/h):1;const dw=w*scale,dh=h*scale;const x=(r.width-dw)/2+state.panX,y=(r.height-dh)/2+state.panY;drawBox={x,y,w:dw,h:dh,scale};const has=!!state.clean,split=Number($('split').value)/100;ctx.drawImage(originalCanvas,x,y,dw,dh);if(has&&state.view!=='before'){ctx.save();if(state.view==='compare'){ctx.beginPath();ctx.rect(r.width*split,0,r.width*(1-split),r.height);ctx.clip();}ctx.drawImage(resultCanvas,x,y,dw,dh);ctx.restore();}if(state.center){const px=x+state.center.x*scale,py=y+state.center.y*scale;ctx.save();ctx.strokeStyle='#d7b9ff';ctx.lineWidth=1;ctx.setLineDash([4,4]);const cw=Math.min(192,w)*scale,ch=Math.min(192,h)*scale;ctx.strokeRect(Math.max(x,Math.min(px-cw/2,x+dw-cw)),Math.max(y,Math.min(py-ch/2,y+dh-ch)),cw,ch);ctx.restore();}$('splitLine').hidden=state.view!=='compare'||!has;$('splitLine').style.left=split*100+'%';$('viewerLabels').hidden=state.view!=='compare'||!has;}
new ResizeObserver(draw).observe($('viewer'));$('split').oninput=draw;for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{state.view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));draw();};$('fit').onclick=()=>{state.zoom='fit';state.panX=0;state.panY=0;draw();};$('actual').onclick=()=>{state.zoom='actual';state.panX=0;state.panY=0;draw();};
let pointer=null;$('display').addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,panX:state.panX,panY:state.panY,moved:false};$('display').setPointerCapture(e.pointerId);});$('display').addEventListener('pointermove',e=>{if(!pointer)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.abs(dx)+Math.abs(dy)>5)pointer.moved=true;if(state.zoom==='actual'&&pointer.moved){const r=$('viewer').getBoundingClientRect();const limitX=Math.max(0,(state.source.width-r.width)/2),limitY=Math.max(0,(state.source.height-r.height)/2);state.panX=Math.max(-limitX,Math.min(limitX,pointer.panX+dx));state.panY=Math.max(-limitY,Math.min(limitY,pointer.panY+dy));draw();}});$('display').addEventListener('pointerup',e=>{if(pointer&&!pointer.moved&&drawBox&&state.source){const r=$('display').getBoundingClientRect(),x=(e.clientX-r.left-drawBox.x)/drawBox.scale,y=(e.clientY-r.top-drawBox.y)/drawBox.scale;state.center={x:Math.max(0,Math.min(state.source.width-1,x)),y:Math.max(0,Math.min(state.source.height-1,y))};draw();}pointer=null;});$('display').addEventListener('pointercancel',()=>pointer=null);
function cancel(tell=true){if(state.worker&&state.busy){state.worker.terminate();state.worker=null;}state.busy=false;state.job=null;canWork();if(tell)status('已停止處理，可以調整設定再試。');}
$('cancel').onclick=()=>cancel();
function processImage(preview){if(!state.source||state.busy)return;const src=state.source;let rect=null,jobData=src;if(preview){const width=Math.min(192,src.width),height=Math.min(192,src.height),x=Math.round(Math.max(0,Math.min(src.width-width,state.center.x-width/2))),y=Math.round(Math.max(0,Math.min(src.height-height,state.center.y-height/2)));rect={x,y,width,height};jobData=originalCanvas.getContext('2d').getImageData(x,y,width,height);}state.busy=true;state.job={rect,generation:state.generation};canWork();status(preview?'正在準備局部預覽…':'正在準備整張圖片…',0);if(!state.worker){state.worker=new Worker('worker.js');state.worker.onmessage=e=>{const msg=e.data;if(msg.type==='progress'){status(msg.text,msg.pct);return;}if(msg.type==='engine'){$('engine').textContent=msg.engine;return;}if(msg.type==='error'){state.busy=false;state.job=null;canWork();status('處理失敗：'+msg.message+' 可切換 CPU 或強力去紋理再試。');return;}if(msg.type==='done'){const job=state.job;if(!job||job.generation!==state.generation)return;state.clean=new Uint8ClampedArray(msg.buffer);state.region=job.rect;state.busy=false;state.job=null;$('cropBadge').hidden=!state.region;$('engine').textContent=msg.engine;renderResult();draw();canWork();const sec=(msg.ms/1000).toFixed(1);status(state.region?`局部預覽完成 · ${sec} 秒。滿意後請按「清理整張圖片」。`:`整張清理完成 · ${sec} 秒，可以下載了。`);$('exportHint').textContent=state.region?'目前只有局部預覽，請先完成整張處理。':'可隨時調整效果混合，再下載整張圖片。';}};state.worker.onerror=e=>{cancel(false);state.worker?.terminate();state.worker=null;status('背景處理發生錯誤：'+(e.message||'請確認 WebView2 已更新，或改用強力去紋理。'));};}const buffer=new Uint8ClampedArray(jobData.data).buffer;state.worker.postMessage({cacheKey:state.generation+':'+(rect?[rect.x,rect.y,rect.width,rect.height].join(','):'full'),mode:state.mode,backend:$('backend').value,noise:Number($('noise').value),textureStrength:Number($('texture').value),textureRadius:Number($('radius').value),width:jobData.width,height:jobData.height,buffer},[buffer]);}
$('preview').onclick=()=>processImage(true);$('run').onclick=()=>processImage(false);
$('save').onclick=async()=>{if(!state.clean||state.region||state.busy)return;const type=$('format').value;try{renderResult();let c=resultCanvas;if(type==='image/jpeg'){c=document.createElement('canvas');c.width=resultCanvas.width;c.height=resultCanvas.height;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(resultCanvas,0,0);}const blob=await new Promise(resolve=>c.toBlob(resolve,type,.95));if(!blob)throw new Error('圖片編碼失敗，請改用 PNG。');const ext=blob.type==='image/jpeg'?'jpg':blob.type==='image/webp'?'webp':'png',url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=state.name.replace(/\.[^.]+$/,'')+'_clean.'+ext;if(typeof window.whetstoneSaveImage==='function'){URL.revokeObjectURL(url);const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('無法讀取輸出圖片'));reader.readAsDataURL(blob);});const saved=await window.whetstoneSaveImage(a.download,String(dataUrl).split(',')[1]);status(saved?'圖片已儲存 · '+saved:'已取消儲存。');}else{a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);status('圖片已匯出 · '+ext.toUpperCase());}}catch(e){status(e.message);}};
$('demo').onclick=()=>{loadSerial++;const w=640,h=480,c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');let g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,'#c5a9c1');g.addColorStop(1,'#746c94');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);ctx.fillStyle='#e5c7a4';ctx.beginPath();ctx.arc(446,139,59,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8b6d9b';ctx.beginPath();ctx.moveTo(0,400);ctx.bezierCurveTo(95,190,181,150,320,370);ctx.bezierCurveTo(420,480,550,194,640,303);ctx.lineTo(640,480);ctx.lineTo(0,480);ctx.fill();ctx.fillStyle='#423752';ctx.beginPath();ctx.moveTo(0,425);ctx.bezierCurveTo(186,291,294,539,640,364);ctx.lineTo(640,480);ctx.lineTo(0,480);ctx.fill();ctx.strokeStyle='#ead0cf';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(188,392);ctx.bezierCurveTo(227,338,266,385,309,358);ctx.stroke();const d=ctx.getImageData(0,0,w,h);let seed=42;function rand(){seed=(1664525*seed+1013904223)>>>0;return(seed+.5)/4294967296;}for(let p=0;p<d.data.length;p+=4){const n=Math.sqrt(-2*Math.log(rand()))*Math.cos(2*Math.PI*rand())*15;for(let k=0;k<3;k++)d.data[p+k]+=n+(rand()-.5)*8;}installImage(d,'磨石範例.png');};
$('helpBtn').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();$('help').addEventListener('click',e=>{if(e.target===$('help')){const r=$('help').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('help').close();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();if(!isLocal){installPrompt=e;$('install').hidden=false;}});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true;}};
const isLocal=['127.0.0.1','localhost','terminal.local'].includes(location.hostname);
if(isLocal){$('cacheOffline').hidden=true;$('cacheStatus').textContent='Windows 本機版已內含全部模型，不需另外準備離線資料。';}
if('serviceWorker' in navigator&&!isLocal){navigator.serviceWorker.register('sw.js').catch(()=>{});}
$('cacheOffline').onclick=async()=>{try{if(!('serviceWorker'in navigator))throw new Error('此瀏覽器不支援離線快取。');if(location.protocol==='file:')throw new Error('請透過 Windows 程式或 HTTPS 開啟此工具。');$('cacheOffline').disabled=true;$('cacheStatus').textContent='正在準備離線快取…';const reg=await navigator.serviceWorker.ready;const channel=new MessageChannel();channel.port1.onmessage=e=>{const d=e.data;$('cacheStatus').textContent=d.text;if(d.done||d.error)$('cacheOffline').disabled=false;};reg.active.postMessage({type:'cache-model'},[channel.port2]);}catch(e){$('cacheStatus').textContent=e.message;$('cacheOffline').disabled=false;}};
if(window.whetstoneDesktop){$('save').textContent='另存圖片 ↓';document.querySelector('.local').lastChild.textContent=' 桌面版 · 本機處理';$('install').hidden=true;}
if(location.protocol==='file:')status('請從 Whetstone.exe 啟動；直接開啟 HTML 無法載入完整 AI 模型。');
